\begin{lemma}
\label{lemma-ubiquity-J-2}
The following types of schemes are J-2.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Noetherian local ring
of dimension $1$.
\item Any scheme locally of finite type over a Nagata ring of dimension $1$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\item And so on.
\end{enumerate}
\end{lemma}

\begin{proof}
By Lemma \ref{lemma-J} we only need to show that
the rings mentioned above are J-2. For this see
More on Algebra, Proposition \ref{more-algebra-proposition-ubiquity-J-2}.
\end{proof}

\begin{definition}
\label{definition-excellent}
Let $X$ be a scheme.
\begin{enumerate}
\item We say $X$ is {\it quasi-excellent} if for every $x \in X$ there exists
an affine open neighbourhood $x \in U \subset X$ such that the ring
$\mathcal{O}_X(U)$ is quasi-excellent (see
More on Algebra, Definition \ref{more-algebra-definition-excellent}).
\item We say $X$ is {\it excellent} if for every $x \in X$ there exists an
affine open neighbourhood $x \in U \subset X$ such that the ring
$\mathcal{O}_X(U)$ is excellent (see
More on Algebra, Definition \ref{more-algebra-definition-excellent}).
\end{enumerate}
\end{definition}

\begin{lemma}
\label{lemma-characterize-quasi-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-excellent, and
\item $X$ is a G-scheme and J-2.
\end{enumerate}
\end{lemma}

\begin{lemma}
\label{lemma-quasi-excellent-nagata}
A quasi-excellent scheme is Nagata.
\end{lemma}

\begin{proof}
See More on Algebra, Lemma \ref{more-algebra-lemma-quasi-excellent-nagata}.
\end{proof}

\begin{lemma}
\label{lemma-characterize-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is excellent, and
\item $X$ is quasi-excellent and universally catenary.
\end{enumerate}
\end{lemma}

\begin{lemma}
\label{lemma-locally-excellent}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item The scheme $X$ is (quasi-)excellent.
\item For every affine open $U \subset X$ the ring $\mathcal{O}_X(U)$
is (quasi-)excellent.
\item There exists an affine open covering $X = \bigcup U_i$ such that
each $\mathcal{O}_X(U_i)$ is (quasi-)excellent.
\item There exists an open covering $X = \bigcup X_j$
such that each open subscheme $X_j$ is (quasi-)excellent.
\end{enumerate}
Moreover, if $X$ is (quasi-)excellent then every open subscheme
is (quasi-)excellent.
\end{lemma}

\begin{lemma}
\label{lemma-finite-type-excellent}
Let $f : X \to S$ be a morphism.
If $S$ is (quasi-)excellent and $f$ locally of finite type then
$X$ is (quasi-)excellent.
\end{lemma}

\begin{proof}
See More on Algebra, Lemma \ref{more-algebra-lemma-finite-type-over-excellent}.
\end{proof}

\begin{lemma}
\label{lemma-ubiquity-excellent}
The following types of schemes are excellent.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\end{enumerate}
\end{lemma}

\begin{proof}
By Lemmas \ref{lemma-locally-excellent} and \ref{lemma-finite-type-excellent}
we only need to show that the rings mentioned above are excellent.
For this see
More on Algebra, Proposition \ref{more-algebra-proposition-ubiquity-excellent}.
\end{proof}

\begin{definition}
\label{definition-quasi-finite}
\begin{reference}
\cite[II Definition 6.2.3]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item We say that $f$ is {\it quasi-finite at a point $x \in X$}
if there exist an affine neighbourhood $\Spec(A) = U \subset X$
of $x$ and an affine open $\Spec(R) = V \subset S$ such that
$f(U) \subset V$, the ring map $R \to A$ is of finite type,
and $R \to A$ is quasi-finite at the prime of $A$ corresponding to $x$
(see above).
\item We say $f$ is {\it locally quasi-finite} if $f$ is
quasi-finite at every point $x$ of $X$.
\item We say that $f$ is {\it quasi-finite} if $f$ is of finite type
and every point $x$ is an isolated point of its fibre.
\end{enumerate}
\end{definition}

\begin{lemma}
\label{lemma-algebraic-residue-field-extension-closed-point-fibre}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point. Set $s = f(x)$.
If $\kappa(x)/\kappa(s)$
is an algebraic field extension, then
\begin{enumerate}
\item $x$ is a closed point of its fibre, and
\item if in addition $s$ is a closed point of $S$, then
$x$ is a closed point of $X$.
\end{enumerate}
\end{lemma}

\begin{lemma}
\label{lemma-closed-point-fibre-locally-finite-type}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point. Set $s = f(x)$.
Assume $f$ is locally of finite type.
Then $x$ is a closed point of its fibre
if and only if $\kappa(x)/\kappa(s)$ is
a finite field extension.
\end{lemma}

\begin{lemma}
\label{lemma-base-change-closed-point-fibre-locally-finite-type}
Let $f : X \to S$ be a morphism of schemes which is locally of finite type.
Let $g : S' \to S$ be any morphism. Denote $f' : X' \to S'$ the base change.
If $x' \in X'$ maps to a point $x \in X$ which is closed in $X_{f(x)}$
then $x'$ is closed in $X'_{f'(x')}$.
\end{lemma}

\begin{lemma}
\label{lemma-residue-field-quasi-finite}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point. Set $s = f(x)$.
If $f$ is quasi-finite at $x$, then the residue field
extension $\kappa(x)/\kappa(s)$ is finite.
\end{lemma}

\begin{proof}
This is clear from Algebra, Definition \ref{algebra-definition-quasi-finite}.
\end{proof}
